import multiprocessing as mp, sys, time, json
sys.path.insert(0,'/app')

def updater(n):
    import catalog
    for i in range(n):
        catalog.update_price(5, 1000.0 + i)

def reader(bar, out, stop_at):
    import catalog
    bad = 0
    while time.time() < stop_at:
        p = catalog.get_product(5)
        # price must always be a value the updater actually wrote (or the original)
        if not (p["price"] == 50.0 or (1000.0 <= p["price"] < 1000.0 + 60)):
            bad += 1
    out.put(bad)

if __name__ == "__main__":
    import catalog
    print("original price:", catalog.get_product(5)["price"])
    q = mp.Queue(); stop = time.time() + 4
    procs = [mp.Process(target=updater, args=(60,))] + [mp.Process(target=reader, args=(None,q,stop)) for _ in range(6)]
    for p in procs: p.start()
    for p in procs: p.join()
    bads = []
    while not q.empty(): bads.append(q.get())
    print("readers that ever saw a stale/foreign price:", sum(bads), "of", len(bads))
    print("final price after all updates:", catalog.get_product(5)["price"])
